contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(this) && caller != address(0));
        vm.assume(amount > 0);
        // Record state before the call
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(caller);
        // Attempt burn from the fuzzed caller (not owner)
        vm.prank(caller);
        bool ok = true;
        try c.burn(amount) {} catch { ok = false; }
        uint256 totalSupplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(caller);
        // Rule: If the call succeeded (did not revert), then totalSupply must decrease by exactly amount
        // and the caller's balance must decrease by exactly amount (i.e., caller had sufficient balance).
        // If the caller had insufficient balance or was frozen, the call should revert.
        // The buggy version removes the onlyOwner check, allowing arbitrary callers to succeed even with 0 balance.
        if (ok) {
            // Successful burn implies the caller must have had enough balance
            assertTrue(totalSupplyBefore - totalSupplyAfter == amount && balanceBefore - balanceAfter == amount);
        }
    }
}

